import { readFileSync, writeFileSync, renameSync, existsSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import path from 'node:path';

export function createStore(filePath) {
  let books = [];

  if (existsSync(filePath)) {
    books = JSON.parse(readFileSync(filePath, 'utf8'));
  }

  function save() {
    // write-then-rename so a crash mid-write can't corrupt the file
    const tmp = path.join(path.dirname(filePath), `.${path.basename(filePath)}.tmp`);
    writeFileSync(tmp, JSON.stringify(books, null, 2) + '\n');
    renameSync(tmp, filePath);
  }

  return {
    all() {
      return books;
    },
    reading() {
      return books.filter((b) => !b.finishedAt);
    },
    finished() {
      return books.filter((b) => b.finishedAt);
    },
    get(id) {
      return books.find((b) => b.id === id) ?? null;
    },
    add({ title, author, notes = '' }) {
      const book = {
        id: randomUUID(),
        title: title.trim(),
        author: author.trim(),
        notes: notes.trim(),
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.push(book);
      save();
      return book;
    },
    finish(id) {
      const book = this.get(id);
      if (!book) return null;
      if (!book.finishedAt) {
        book.finishedAt = new Date().toISOString();
        save();
      }
      return book;
    },
  };
}

