import http from 'node:http';
import { createStore } from './store.mjs';

export function createServer(store) {
  return http.createServer(async (req, res) => {
    const url = new URL(req.url, 'http://localhost');

    if (req.method === 'GET' && url.pathname === '/') {
      return sendHtml(res, 200, homePage(store));
    }

    let m = url.pathname.match(/^\/book\/([\w-]+)$/);
    if (req.method === 'GET' && m) {
      const book = store.get(m[1]);
      if (!book) return notFound(res);
      return sendHtml(res, 200, bookPage(book));
    }

    if (req.method === 'POST' && url.pathname === '/add') {
      const form = await readForm(req);
      if (!form.get('title')?.trim() || !form.get('author')?.trim()) {
        return sendHtml(res, 400, errorPage('Title and author are required.'));
      }
      const book = store.add({
        title: form.get('title'),
        author: form.get('author'),
        notes: form.get('notes') ?? '',
      });
      return redirect(res, `/book/${book.id}`);
    }

    m = url.pathname.match(/^\/book\/([\w-]+)\/finish$/);
    if (req.method === 'POST' && m) {
      const book = store.finish(m[1]);
      if (!book) return notFound(res);
      return redirect(res, `/book/${book.id}`);
    }

    notFound(res);
  });
}

function readForm(req) {
  return new Promise((resolve, reject) => {
    let body = '';
    req.on('data', (chunk) => {
      body += chunk;
      if (body.length > 100_000) req.destroy();
    });
    req.on('end', () => resolve(new URLSearchParams(body)));
    req.on('error', reject);
  });
}

function sendHtml(res, status, html) {
  res.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8' });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

function notFound(res) {
  sendHtml(res, 404, errorPage('Not found.'));
}

const esc = (s) =>
  String(s)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;');

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(title)}</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; color: #222; line-height: 1.5; }
  h1 { font-size: 1.5rem; } h2 { font-size: 1.1rem; margin-top: 2rem; }
  ul { padding-left: 1.2rem; } li { margin: 0.3rem 0; }
  a { color: #1a5dab; }
  .author { color: #666; }
  form.add { display: grid; gap: 0.5rem; margin-top: 0.5rem; }
  input, textarea, button { font: inherit; padding: 0.4rem; }
  button { cursor: pointer; width: fit-content; }
  .muted { color: #888; font-size: 0.9rem; }
  .notes { white-space: pre-wrap; background: #f6f6f6; padding: 0.8rem; border-radius: 6px; }
</style>
</head>
<body>
${body}
</body>
</html>`;
}

function bookList(books) {
  if (books.length === 0) return '<p class="muted">Nothing here yet.</p>';
  return `<ul>${books
    .map(
      (b) =>
        `<li><a href="/book/${b.id}">${esc(b.title)}</a> <span class="author">by ${esc(b.author)}</span></li>`
    )
    .join('\n')}</ul>`;
}

function homePage(store) {
  return layout(
    'My books',
    `<h1>My books</h1>

<h2>Currently reading</h2>
${bookList(store.reading())}

<h2>Finished</h2>
${bookList(store.finished())}

<h2>Add a book</h2>
<form class="add" method="post" action="/add">
  <input name="title" placeholder="Title" required>
  <input name="author" placeholder="Author" required>
  <textarea name="notes" placeholder="Notes (optional)" rows="4"></textarea>
  <button type="submit">Add book</button>
</form>`
  );
}

function bookPage(book) {
  const status = book.finishedAt
    ? `<p class="muted">Finished on ${esc(book.finishedAt.slice(0, 10))}</p>`
    : `<form method="post" action="/book/${book.id}/finish"><button type="submit">Mark as finished</button></form>`;
  return layout(
    book.title,
    `<p><a href="/">&larr; All books</a></p>
<h1>${esc(book.title)}</h1>
<p class="author">by ${esc(book.author)}</p>
${status}
<h2>Notes</h2>
${book.notes ? `<div class="notes">${esc(book.notes)}</div>` : '<p class="muted">No notes.</p>'}`
  );
}

function errorPage(message) {
  return layout('Error', `<h1>${esc(message)}</h1><p><a href="/">&larr; All books</a></p>`);
}

if (process.argv[1] === new URL(import.meta.url).pathname) {
  const port = Number(process.env.PORT ?? 3000);
  const store = createStore(process.env.BOOKS_FILE ?? new URL('../books.json', import.meta.url).pathname);
  createServer(store).listen(port, () => {
    console.log(`Book tracker running at http://localhost:${port}`);
  });
}

