import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { mkdtempSync, rmSync, readFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { createStore } from '../src/store.mjs';
import { createServer } from '../src/server.mjs';

let dir, file, store;

beforeEach(() => {
  dir = mkdtempSync(path.join(tmpdir(), 'books-'));
  file = path.join(dir, 'books.json');
  store = createStore(file);
});

afterEach(() => {
  rmSync(dir, { recursive: true, force: true });
});

describe('store', () => {
  it('adds a book as currently reading', () => {
    const book = store.add({ title: 'Dune', author: 'Frank Herbert', notes: 'ch. 1' });
    expect(store.reading()).toHaveLength(1);
    expect(store.finished()).toHaveLength(0);
    expect(store.get(book.id).title).toBe('Dune');
  });

  it('marks a book finished', () => {
    const book = store.add({ title: 'Dune', author: 'Frank Herbert' });
    store.finish(book.id);
    expect(store.reading()).toHaveLength(0);
    expect(store.finished()).toHaveLength(1);
  });

  it('persists to the JSON file across restarts', () => {
    const book = store.add({ title: 'Dune', author: 'Frank Herbert', notes: 'sand' });
    store.finish(book.id);

    const reloaded = createStore(file);
    expect(reloaded.finished()).toHaveLength(1);
    expect(reloaded.get(book.id).notes).toBe('sand');
    expect(JSON.parse(readFileSync(file, 'utf8'))).toHaveLength(1);
  });

  it('returns null for unknown ids', () => {
    expect(store.get('nope')).toBeNull();
    expect(store.finish('nope')).toBeNull();
  });
});

describe('server', () => {
  let server, base;

  beforeEach(async () => {
    server = createServer(store);
    await new Promise((r) => server.listen(0, r));
    base = `http://localhost:${server.address().port}`;
  });

  afterEach(() => new Promise((r) => server.close(r)));

  const postForm = (url, data, opts = {}) =>
    fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams(data),
      ...opts,
    });

  it('shows reading and finished sections on the home page', async () => {
    store.add({ title: 'Dune', author: 'Frank Herbert' });
    store.finish(store.add({ title: 'Emma', author: 'Jane Austen' }).id);
    const html = await (await fetch(base + '/')).text();
    expect(html).toContain('Currently reading');
    expect(html).toContain('Dune');
    expect(html).toContain('Emma');
  });

  it('adds a book via the form and redirects to its page', async () => {
    const res = await postForm(base + '/add', { title: 'Dune', author: 'Frank Herbert', notes: 'spice' }, { redirect: 'manual' });
    expect(res.status).toBe(303);
    const html = await (await fetch(base + res.headers.get('location'))).text();
    expect(html).toContain('Dune');
    expect(html).toContain('Frank Herbert');
    expect(html).toContain('spice');
  });

  it('rejects a book without a title', async () => {
    const res = await postForm(base + '/add', { title: ' ', author: 'x' });
    expect(res.status).toBe(400);
  });

  it('marks a book finished via the button', async () => {
    const book = store.add({ title: 'Dune', author: 'Frank Herbert' });
    const res = await postForm(`${base}/book/${book.id}/finish`, {});
    expect(res.status).toBe(200);
    expect(store.get(book.id).finishedAt).toBeTruthy();
    expect(await res.text()).toContain('Finished on');
  });

  it('serves a shareable per-book link and 404s unknown books', async () => {
    const book = store.add({ title: 'Dune', author: 'Frank Herbert' });
    expect((await fetch(`${base}/book/${book.id}`)).status).toBe(200);
    expect((await fetch(`${base}/book/does-not-exist`)).status).toBe(404);
  });

  it('escapes HTML in user input', async () => {
    const book = store.add({ title: '<script>alert(1)</script>', author: 'x' });
    const html = await (await fetch(`${base}/book/${book.id}`)).text();
    expect(html).not.toContain('<script>alert');
    expect(html).toContain('&lt;script&gt;');
  });
});

